WITH department_summary AS (SELECT dept_id, SUM(CASE WHEN job_title = 'Manager' THEN salary ELSE 0 END) AS manager_salary FROM employees GROUP BY dept_id) SELECT departments.id, departments.budget, departments.location, department_summary.manager_salary FROM departments JOIN department_summary ON departments.id = department_summary.dept_id WHERE department_summary.manager_salary >= 80 ORDER BY department_summary.manager_salary DESC
